INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (47684,0,0,'Welcome to my lands, $r. The little one told me you seek information on the legend of Irmaat.',12,0,100.0,1,0,0,104090,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (97774,0,0,'Give up! You only strike at the wind!',14,0,100.0,0,0,0,99833,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (97774,1,0,'Begone, foul creature! You will not harm any more of our sacred texts!',14,0,100.0,0,0,0,100131,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (97774,3,0,'Thank you, friend! My students died to protect these scrolls. Centuries of history could have been lost!',12,0,100.0,0,0,0,99838,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (97774,4,0,'Chen Stormstout was teaching a class of youngsters when the attack began. He\'s one of the strongest monks I know, but even he won\'t be able to hold out forever. Come, we must rescue them!',12,0,100.0,0,0,0,99847,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (97774,5,0,'No good! We don\'t have time to fight our way through that horde!',12,0,100.0,0,0,0,99901,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (97774,6,0,'If I focus my Chi, I believe I can get us behind their forces. Quickly, $n. Take my hand.',12,0,100.0,0,0,0,100145,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (97774,7,0,'This is worse then I feared. $n! We must part ways. They need my help here at the temple. Chen\'s class should be just to the north across the bridges.',12,0,100.0,0,0,0,100149,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (97774,8,0,'Jade Serpent watch over you, $n.',12,0,100.0,0,0,0,100185,0,'LegionCore');
