INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (99179,0,0,'Chen and Li Li are strong allies for our order, and I know just how we can use them.',12,0,100.0,1,0,0,116315,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (99181,0,0,'%s motions for you to follow.',16,0,100.0,0,0,0,102052,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (99181,1,0,'%s nods approvingly.',16,0,100.0,0,0,0,102056,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (99181,2,0,'But as we teetered upon the brink of annihilation, $n stayed with Grand Master Hight and fought the demons to ensure our survival.',12,0,100.0,0,0,0,102076,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (99181,3,0,'Grand Master Hight has passed on to join the ancestors, and we are left with a void in our ranks.',12,0,100.0,0,0,0,102078,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (99181,4,0,'It seems fitting that the hero who fought at his side, who displayed courage and valor immeasurable, should succeed him.',12,0,100.0,0,0,0,102089,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (100355,0,0,'Excellent! I have everything prepared inside. Follow me.',12,0,100.0,0,0,0,102087,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (100355,1,0,'To all members and students of our combined schools, I offer you my thanks for joining us.',12,0,100.0,0,0,0,102070,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (100355,2,0,'The attack at the Peak of Serenity shows that the Burning Legion wishes to shatter our order. They will destroy our homes, defile our sacred temples, and strive to break our spirit.',12,0,100.0,0,0,0,102073,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (100355,3,0,'Let us all give honor to Master $n! May she lead us with strength and wisdom.',12,0,100.0,0,0,0,102080,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (100355,4,0,'Monks, our greatest challenge still lies ahead. Under our new master, we will send a message of defiance to our enemies. They will not take our home without a fight!',12,0,100.0,0,0,0,102077,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (100438,0,0,'$ct, Li Li should be at the Laughing Crane. That\'s the village inn just down the stairs from the temple.',12,0,100.0,0,0,0,104761,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (100438,1,0,'Hurry, Grandmaster! The battle rages on the ridge above us. You\'d better join them quickly!',12,0,100.0,5,0,0,116322,0,'LegionCore');
