INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (100475,0,0,'Okay, Pop. It\'s been... it\'s been something. I need to get on with my travels.',12,0,100.0,1,0,61994,103325,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (100475,1,0,'I thought you might say that... Look, I have a guardian, and it\'s even the master of the monks. I\'ll be fine!',12,0,100.0,0,0,61996,103327,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (100475,2,0,'Yay! Okay $n, let\'s go!',12,0,100.0,0,0,61998,103335,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (100475,3,0,'My friend Mr. Crane can fly me to Uldum. Here, you can use my kite to follow us.',12,0,100.0,0,0,61999,103339,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (100475,4,0,'Okay, Mr. Crane. Here\'s two juicy fish if you\'ll take me to Uldum.',12,0,100.0,0,0,62000,103340,0,'LegionCore');
