INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (102855,0,0,'You will get no further than us, Lady Keletress!',12,0,100.0,603,0,71476,122297,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (102855,1,0,'The Legion witch is dead. Grandmaster, I think this calls for a celebration!',12,0,100.0,0,0,71475,107898,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (102902,3,0,'The master chose well, all will see! The Monkey King is tough as can be!',12,0,100.0,4,0,66659,107555,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (102996,0,0,'This is right place. We will find the stolen recipe here.',12,0,100.0,0,0,66631,105379,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (102996,3,0,'My master, Melba, taught me everything she knew, including the fighting techniques of ancient vrykul brewer-kings and queens.',12,0,100.0,1,0,66641,105462,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (102996,4,0,'Yes, now that\'s strong! But my master\'s was still better.',12,0,100.0,5,0,66632,105383,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (103148,0,0,'Chuang!',14,0,100.0,0,0,0,107053,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (103148,1,0,'Li Li, let\'s go check on the little ones.',12,0,100.0,0,0,0,107055,0,'LegionCore');
