INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (120758,0,0,'Xuen, the White Tiger, one of the August Celestials, had a son named Ban-Lu.',12,0,100.0,0,0,82387,128481,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (120758,1,0,'Over the centuries, Ban-Lu served as the personal mount of each grandmaster. It was a duty he was honored to fulfil!',12,0,100.0,0,0,82388,128482,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (120758,2,0,'But Ban-Lu has not been seen since the Legion\'s attack on the Peak of Serenity. It seems the loss of life... affected him deeply.',12,0,100.0,1,0,82389,128483,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (120758,3,0,'Perhaps if we return there, we may find clues to his whereabouts.',12,0,100.0,1,0,82390,128484,0,'LegionCore');
